 16	func (s *Server) createPayment(w http.ResponseWriter, r *http.Request) {
 17		var req createPaymentRequest
 18		if err := decodeJSON(r, &req); err != nil {
 19			writeError(w, err)
 20			return
 21		}
 22		amount, err := money.Parse(req.Amount, req.Currency)
 23		if err != nil {
 24			writeError(w, fmt.Errorf("amount: %w", err))
 25			return
 26		}
 27		in := payment.CreateInput{MerchantID: req.MerchantID, Amount: amount}
 28		s.idempotent(w, r, createFingerprint(in), func() (int, any) {
 29			p, err := s.svc.Create(r.Context(), in)
 30			if err != nil {
 31				return errorResponse(err)
 32			}
 33			return http.StatusCreated, toPaymentResponse(p)
 34		})
 35	}
 36	
 37	func (s *Server) getPayment(w http.ResponseWriter, r *http.Request) {
 38		p, err := s.svc.Get(r.Context(), r.PathValue("id"))
 39		if err != nil {
 40			writeError(w, err)
 41			return
 42		}
 43		writeJSON(w, http.StatusOK, toPaymentResponse(p))
 44	}
 45	
 46	func (s *Server) authorizePayment(w http.ResponseWriter, r *http.Request) {
 47		s.respondPayment(w, func() (payment.Payment, error) { return s.svc.Authorize(r.Context(), r.PathValue("id")) })
 48	}
 49	
 50	func (s *Server) capturePayment(w http.ResponseWriter, r *http.Request) {
 51		s.respondPayment(w, func() (payment.Payment, error) { return s.svc.Capture(r.Context(), r.PathValue("id")) })
 52	}
 53	
 54	func (s *Server) declinePayment(w http.ResponseWriter, r *http.Request) {
 55		var req declineRequest
 56		if r.ContentLength != 0 {
 57			if err := decodeJSON(r, &req); err != nil {
 58				writeError(w, err)
 59				return
 60			}
 61		}
 62		s.respondPayment(w, func() (payment.Payment, error) {
 63			return s.svc.Decline(r.Context(), r.PathValue("id"), req.Reason)
 64		})
 65	}
 66	
 67	func (s *Server) refundPayment(w http.ResponseWriter, r *http.Request) {
 68		id := r.PathValue("id")
 69		var req refundRequest
 70		if err := decodeJSON(r, &req); err != nil {
 71			writeError(w, err)
 72			return
 73		}
 74		p, err := s.svc.Get(r.Context(), id)
 75		if err != nil {
 76			writeError(w, err)
 77			return
 78		}
 79		amount, err := money.Parse(req.Amount, p.Amount.Currency.Code)
 80		if err != nil {
 81			writeError(w, fmt.Errorf("amount: %w", err))
 82			return
 83		}
 84		s.idempotent(w, r, refundFingerprint(id, amount), func() (int, any) {
 85			p, _, err := s.svc.Refund(r.Context(), id, amount)
 86			if err != nil {
 87				return errorResponse(err)
 88			}
 89			return http.StatusCreated, toPaymentResponse(p)
 90		})
 91	}
 92	
 93	func (s *Server) listPayments(w http.ResponseWriter, r *http.Request) {
 94		q := r.URL.Query()
 95		page := payment.Page{Cursor: q.Get("cursor")}
 96		if v := q.Get("limit"); v != "" {
 97			n, err := strconv.Atoi(v)
 98			if err != nil {
 99				writeError(w, fmt.Errorf("%w: limit %q is not a number", payment.ErrInvalidInput, v))
100				return
101			}
102			page.Limit = n
103		}
104		ps, next, err := s.svc.List(r.Context(), r.PathValue("merchantID"), page)
105		if err != nil {
106			writeError(w, err)
107			return
108		}
109		out := listResponse{Data: make([]paymentResponse, 0, len(ps)), NextCursor: next}
110		for _, p := range ps {
111			out.Data = append(out.Data, toPaymentResponse(p))
112		}
113		writeJSON(w, http.StatusOK, out)
114	}
115	
116	func (s *Server) listDeadLetters(w http.ResponseWriter, _ *http.Request) {
117		dead := s.hooks.DeadLetters()
118		out := make([]deadLetterResponse, 0, len(dead))
119		for _, d := range dead {
120			out = append(out, toDeadLetterResponse(d))
121		}
122		writeJSON(w, http.StatusOK, map[string]any{"data": out})
123	}
124	
125	func (s *Server) respondPayment(w http.ResponseWriter, op func() (payment.Payment, error)) {
126		p, err := op()
127		if err != nil {
128			writeError(w, err)
129			return
130		}
131		writeJSON(w, http.StatusOK, toPaymentResponse(p))
132	}
133	
134	func decodeJSON(r *http.Request, dst any) error {
135		dec := json.NewDecoder(io.LimitReader(r.Body, maxBodyBytes))
136		dec.DisallowUnknownFields()
137		if err := dec.Decode(dst); err != nil {
138			return fmt.Errorf("%w: malformed JSON body: %v", payment.ErrInvalidInput, err)
139		}
140		return nil
141	}
142	
143	func writeJSON(w http.ResponseWriter, status int, body any) {
144		w.Header().Set("Content-Type", "application/json")
145		w.WriteHeader(status)
146		_ = json.NewEncoder(w).Encode(body)
147	}

  1	// Package webhook delivers payment events to merchant endpoints with signed
  2	// payloads, retries with exponential backoff and a dead-letter list.
  3	package webhook
  4	
  5	import (
  6		"context"
  7		"encoding/json"
  8		"fmt"
  9		"net/http"
 10		"sync"
 11		"time"
 12	
 13		"example.com/gopayments/clock"
 14		"example.com/gopayments/payment"
 15	)
 16	
 17	// Event is the webhook payload.
 18	type Event struct {
 19		ID         string          `json:"id"`
 20		Type       string          `json:"type"`
 21		MerchantID string          `json:"merchant_id"`
 22		CreatedAt  time.Time       `json:"created_at"`
 23		Data       json.RawMessage `json:"data"`
 24	}
 25	
 26	// Endpoint is a merchant's webhook destination.
 27	type Endpoint struct {
 28		URL    string
 29		Secret string
 30	}
 31	
 32	// Endpoints resolves the endpoint of a merchant.
 33	type Endpoints interface {
 34		Endpoint(merchantID string) (Endpoint, bool)
 35	}
 36	
 37	// StaticEndpoints is a fixed merchant -> endpoint map.
 38	type StaticEndpoints map[string]Endpoint
 39	
 40	// Endpoint implements Endpoints.
 41	func (s StaticEndpoints) Endpoint(merchantID string) (Endpoint, bool) {
 42		e, ok := s[merchantID]
 43		return e, ok
 44	}
 45	
 46	// Policy controls retries.
 47	type Policy struct {
 48		MaxAttempts int
 49		BaseDelay   time.Duration
 50		MaxDelay    time.Duration
 51	}
 52	
 53	// DefaultPolicy is the production retry policy.
 54	func DefaultPolicy() Policy {
 55		return Policy{MaxAttempts: 6, BaseDelay: time.Second, MaxDelay: 10 * time.Minute}
 56	}
 57	
 58	// Backoff is the wait after failed attempt n (n >= 1): BaseDelay * 2^(n-1),
 59	// capped at MaxDelay.
 60	func (p Policy) Backoff(n int) time.Duration {
 61		d := p.BaseDelay
 62		for i := 1; i < n; i++ {
 63			if d >= p.MaxDelay/2 {
 64				return p.MaxDelay
 65			}
 66			d *= 2
 67		}
 68		return min(d, p.MaxDelay)
 69	}
 70	
 71	// DeadLetter is an event that exhausted its retries or failed permanently.
 72	type DeadLetter struct {
 73		Event      Event
 74		Attempts   int
 75		LastStatus int
 76		LastError  string
 77		FailedAt   time.Time
 78	}
 79	
 80	// Dispatcher queues events and delivers them.
 81	type Dispatcher struct {
 82		sender    Sender
 83		endpoints Endpoints
 84		clock     clock.Clock
 85		policy    Policy
 86	
 87		mu        sync.Mutex
 88		seq       int
 89		queue     []Event
 90		dead      []DeadLetter
 91		delivered int
 92	}
 93	
 94	var _ payment.Publisher = (*Dispatcher)(nil)
 95	
 96	// NewDispatcher wires a dispatcher.
 97	func NewDispatcher(sender Sender, endpoints Endpoints, clk clock.Clock, policy Policy) *Dispatcher {
 98		return &Dispatcher{sender: sender, endpoints: endpoints, clock: clk, policy: policy}
 99	}
100	
101	type paymentData struct {
102		PaymentID string `json:"payment_id"`
103		Status    string `json:"status"`
104		Amount    string `json:"amount"`
105		Currency  string `json:"currency"`
106		Refunded  string `json:"refunded_amount"`
107		RefundID  string `json:"refund_id,omitempty"`
108	}
109	
110	// Publish implements payment.Publisher by queueing a webhook event.
111	func (d *Dispatcher) Publish(_ context.Context, ev payment.Event) error {
112		data := paymentData{
113			PaymentID: ev.Payment.ID,
114			Status:    string(ev.Payment.Status),
115			Amount:    ev.Payment.Amount.Decimal(),
116			Currency:  ev.Payment.Amount.Currency.Code,
117			Refunded:  ev.Payment.RefundedAmount().Decimal(),
118		}
119		if ev.Refund != nil {
120			data.RefundID = ev.Refund.ID
121		}
122		raw, err := json.Marshal(data)
123		if err != nil {
124			return fmt.Errorf("encode %s event: %w", ev.Type, err)
125		}
126		d.mu.Lock()
127		defer d.mu.Unlock()
128		d.seq++
129		d.queue = append(d.queue, Event{
130			ID:         fmt.Sprintf("evt_%06d", d.seq),
131			Type:       ev.Type,
132			MerchantID: ev.Payment.MerchantID,
133			CreatedAt:  d.clock.Now(),
134			Data:       raw,
135		})
136		return nil
137	}
138	
139	// Pending returns the number of queued, undelivered events.
140	func (d *Dispatcher) Pending() int {
141		d.mu.Lock()
142		defer d.mu.Unlock()
143		return len(d.queue)
144	}
145	
146	// Delivered returns how many events were delivered successfully.
147	func (d *Dispatcher) Delivered() int {
148		d.mu.Lock()
149		defer d.mu.Unlock()
150		return d.delivered
151	}
152	
153	// DeadLetters returns a snapshot of the dead-letter list.
154	func (d *Dispatcher) DeadLetters() []DeadLetter {
155		d.mu.Lock()
156		defer d.mu.Unlock()
157		return append([]DeadLetter(nil), d.dead...)
158	}
159	
160	// Flush delivers every queued event. It returns early only if ctx is done;
161	// undelivered events stay queued in that case.
162	func (d *Dispatcher) Flush(ctx context.Context) error {
163		d.mu.Lock()
164		batch := d.queue
165		d.queue = nil
166		d.mu.Unlock()
167	
168		for i, ev := range batch {
169			if err := d.deliver(ctx, ev); err != nil {
170				d.mu.Lock()
171				d.queue = append(append([]Event(nil), batch[i:]...), d.queue...)
172				d.mu.Unlock()
173				return fmt.Errorf("flush webhooks: %w", err)
174			}
175		}
176		return nil
177	}
178	
179	// deliver attempts ev until success, a permanent failure or MaxAttempts.
180	// It only returns an error when ctx is done.
181	func (d *Dispatcher) deliver(ctx context.Context, ev Event) error {
182		ep, ok := d.endpoints.Endpoint(ev.MerchantID)
183		if !ok {
184			return nil // merchant has no webhook configured
185		}
186		body, err := json.Marshal(ev)
187		if err != nil {
188			d.deadLetter(ev, 0, 0, fmt.Errorf("encode event: %w", err))
189			return nil
190		}
191		var (
192			status  int
193			sendErr error
194			attempt int
195		)
196		for attempt = 1; attempt <= d.policy.MaxAttempts; attempt++ {
197			headers := map[string]string{
198				"Content-Type":  "application/json",
199				"Webhook-Id":    ev.ID,
200				SignatureHeader: Sign(ep.Secret, d.clock.Now().Unix(), body),
201			}
202			status, sendErr = d.sender.Send(ctx, Delivery{EventID: ev.ID, URL: ep.URL, Body: body, Headers: headers, Attempt: attempt})
203			if sendErr == nil && status >= 200 && status < 300 {
204				d.mu.Lock()
205				d.delivered++
206				d.mu.Unlock()
207				return nil
208			}
209			if !retryable(status, sendErr) || attempt == d.policy.MaxAttempts {
210				break
211			}
212			if err := d.clock.Sleep(ctx, d.policy.Backoff(attempt)); err != nil {
213				return err
214			}
215		}
216		d.deadLetter(ev, attempt, status, sendErr)
217		return nil
218	}
219	
220	func (d *Dispatcher) deadLetter(ev Event, attempts, status int, err error) {
221		dl := DeadLetter{Event: ev, Attempts: attempts, LastStatus: status, FailedAt: d.clock.Now()}
222		if err != nil {
223			dl.LastError = err.Error()
224		}
225		d.mu.Lock()
226		defer d.mu.Unlock()
227		d.dead = append(d.dead, dl)
228	}
229	
230	// retryable reports whether a failed attempt should be retried: transport
231	// errors, 408, 429 and 5xx are transient; any other status is permanent.
232	func retryable(status int, err error) bool {
233		if err != nil {
234			return true
235		}
236		return status == http.StatusRequestTimeout || status == http.StatusTooManyRequests || status >= 500
237	}

  1	// Package store provides repository implementations for the payment domain.
  2	package store
  3	
  4	import (
  5		"context"
  6		"encoding/base64"
  7		"fmt"
  8		"strconv"
  9		"strings"
 10		"sync"
 11	
 12		"example.com/gopayments/payment"
 13	)
 14	
 15	const (
 16		defaultLimit = 20
 17		maxLimit     = 100
 18	)
 19	
 20	// Memory is an in-memory payment.Repository used in tests and local runs.
 21	type Memory struct {
 22		mu         sync.RWMutex
 23		byID       map[string]payment.Payment
 24		byMerchant map[string][]string // payment ids in creation order
 25	}
 26	
 27	var _ payment.Repository = (*Memory)(nil)
 28	
 29	// NewMemory returns an empty repository.
 30	func NewMemory() *Memory {
 31		return &Memory{
 32			byID:       make(map[string]payment.Payment),
 33			byMerchant: make(map[string][]string),
 34		}
 35	}
 36	
 37	// Create stores a new payment.
 38	func (m *Memory) Create(_ context.Context, p payment.Payment) error {
 39		m.mu.Lock()
 40		defer m.mu.Unlock()
 41		if _, ok := m.byID[p.ID]; ok {
 42			return fmt.Errorf("%w: %s", payment.ErrDuplicate, p.ID)
 43		}
 44		m.byID[p.ID] = p.Clone()
 45		m.byMerchant[p.MerchantID] = append(m.byMerchant[p.MerchantID], p.ID)
 46		return nil
 47	}
 48	
 49	// Get returns a copy of the stored payment.
 50	func (m *Memory) Get(_ context.Context, id string) (payment.Payment, error) {
 51		m.mu.RLock()
 52		defer m.mu.RUnlock()
 53		p, ok := m.byID[id]
 54		if !ok {
 55			return payment.Payment{}, fmt.Errorf("%w: %s", payment.ErrNotFound, id)
 56		}
 57		return p.Clone(), nil
 58	}
 59	
 60	// Update replaces the stored payment if versions match.
 61	func (m *Memory) Update(_ context.Context, p payment.Payment) error {
 62		m.mu.Lock()
 63		defer m.mu.Unlock()
 64		cur, ok := m.byID[p.ID]
 65		if !ok {
 66			return fmt.Errorf("%w: %s", payment.ErrNotFound, p.ID)
 67		}
 68		if cur.Version != p.Version {
 69			return fmt.Errorf("%w: payment %s has version %d, update based on %d", payment.ErrVersionConflict, p.ID, cur.Version, p.Version)
 70		}
 71		next := p.Clone()
 72		next.Version++
 73		m.byID[p.ID] = next
 74		return nil
 75	}
 76	
 77	// ListByMerchant pages through a merchant's payments in creation order.
 78	func (m *Memory) ListByMerchant(_ context.Context, merchantID string, page payment.Page) ([]payment.Payment, string, error) {
 79		limit := page.Limit
 80		switch {
 81		case limit < 0:
 82			return nil, "", fmt.Errorf("%w: limit must not be negative", payment.ErrInvalidInput)
 83		case limit == 0:
 84			limit = defaultLimit
 85		case limit > maxLimit:
 86			limit = maxLimit
 87		}
 88		offset := 0
 89		if page.Cursor != "" {
 90			var err error
 91			if offset, err = decodeCursor(page.Cursor); err != nil {
 92				return nil, "", err
 93			}
 94		}
 95	
 96		m.mu.RLock()
 97		defer m.mu.RUnlock()
 98		ids := m.byMerchant[merchantID]
 99		if offset > len(ids) {
100			offset = len(ids)
101		}
102		end := min(offset+limit, len(ids))
103		out := make([]payment.Payment, 0, end-offset)
104		for _, id := range ids[offset:end] {
105			out = append(out, m.byID[id].Clone())
106		}
107		next := ""
108		if end < len(ids) {
109			next = encodeCursor(end)
110		}
111		return out, next, nil
112	}
113	
114	func encodeCursor(offset int) string {
115		return base64.RawURLEncoding.EncodeToString([]byte("o:" + strconv.Itoa(offset)))
116	}
117	
118	func decodeCursor(c string) (int, error) {
119		raw, err := base64.RawURLEncoding.DecodeString(c)
120		if err != nil {
121			return 0, fmt.Errorf("%w: %v", payment.ErrInvalidCursor, err)
122		}
123		n, ok := strings.CutPrefix(string(raw), "o:")
124		if !ok {
125			return 0, fmt.Errorf("%w: unexpected format", payment.ErrInvalidCursor)
126		}
127		off, err := strconv.Atoi(n)
128		if err != nil || off < 0 {
129			return 0, fmt.Errorf("%w: bad offset %q", payment.ErrInvalidCursor, n)
130		}
131		return off, nil
132	}

