			t.Fatalf("events = %s, want %s", evs, want)
		}
	})
}

func TestCancelErrorsAndTerminalState(t *testing.T) {
	ctx := context.Background()

	t.Run("unknown id", func(t *testing.T) {
		s, _ := newTestService()
		if _, err := s.Cancel(ctx, "pay_missing"); !errors.Is(err, ErrNotFound) {
			t.Fatalf("err = %v, want ErrNotFound", err)
		}
	})

	notCancelable := []struct {
		name string
		prep func(t *testing.T, s *Service) string
	}{
		{
			name: "succeeded",
			prep: func(t *testing.T, s *Service) string { return succeeded(t, s, 100).ID },
		},
		{
			name: "declined",
			prep: func(t *testing.T, s *Service) string {
				p, _ := s.Create(ctx, CreateInput{MerchantID: "m", Amount: money.MustNew(100, "USD")})
				_, _ = s.Decline(ctx, p.ID, "fraud")
				return p.ID
			},
		},
		{
			name: "refunded",
			prep: func(t *testing.T, s *Service) string {
				p := succeeded(t, s, 100)
				_, _, _ = s.Refund(ctx, p.ID, money.MustNew(100, "USD"))
				return p.ID
			},
		},
		{
			name: "already canceled",
			prep: func(t *testing.T, s *Service) string {
				p, _ := s.Create(ctx, CreateInput{MerchantID: "m", Amount: money.MustNew(100, "USD")})
				_, _ = s.Cancel(ctx, p.ID)
				return p.ID
			},
		},
	}
	for _, tt := range notCancelable {
		t.Run("cancel "+tt.name, func(t *testing.T) {
			s, rec := newTestService()
			id := tt.prep(t, s)
			before := len(rec.events)
			if _, err := s.Cancel(ctx, id); !errors.Is(err, ErrInvalidTransition) {
				t.Fatalf("err = %v, want ErrInvalidTransition", err)
			}
			if len(rec.events) != before {
				t.Fatalf("unexpected event emitted on failed cancel: %v", rec.events)
			}
		})
	}

	fromCanceled := []struct {
		name string
		op   func(s *Service, id string) error
	}{
		{"authorize", func(s *Service, id string) error { _, err := s.Authorize(ctx, id); return err }},
		{"capture", func(s *Service, id string) error { _, err := s.Capture(ctx, id); return err }},
		{"decline", func(s *Service, id string) error { _, err := s.Decline(ctx, id, "x"); return err }},
		{"refund", func(s *Service, id string) error { _, _, err := s.Refund(ctx, id, money.MustNew(10, "USD")); return err }},
	}
	for _, tt := range fromCanceled {
		t.Run(tt.name+" canceled", func(t *testing.T) {
			s, _ := newTestService()
			p, _ := s.Create(ctx, CreateInput{MerchantID: "m", Amount: money.MustNew(100, "USD")})
			if _, err := s.Cancel(ctx, p.ID); err != nil {
				t.Fatal(err)
			}
			if err := tt.op(s, p.ID); !errors.Is(err, ErrInvalidTransition) {
				t.Fatalf("err = %v, want ErrInvalidTransition", err)
			}
		})
	}
}

