func TestCancelPaymentHTTPAndWebhook(t *testing.T) {
	clk := clock.NewFake(time.Date(2026, 4, 1, 9, 0, 0, 0, time.UTC))
	sender := &captureSender{}
	eps := webhook.StaticEndpoints{"m_1": {URL: "https://merchant.example/hooks", Secret: "sec"}}
	hooks := webhook.NewDispatcher(sender, eps, clk, webhook.DefaultPolicy())
	svc := payment.NewService(store.NewMemory(), clk, payment.NewSeqIDs(), hooks, payment.Config{FeeBps: 290})
	a := &testAPI{t: t, srv: NewServer(svc, idempotency.NewMemory(clk, 24*time.Hour), hooks), clk: clk, hooks: hooks}

	// Cancel CREATED payment.
	created := decode[paymentResponse](t, a.do("POST", "/payments", `{"merchant_id":"m_1","amount":"25.00","currency":"USD"}`))
	rec := a.do("POST", "/payments/"+created.ID+"/cancel", "")
	if rec.Code != http.StatusOK {
		t.Fatalf("cancel created: %d %s", rec.Code, rec.Body)
	}
	canceled := decode[paymentResponse](t, rec)
	if canceled.Status != "CANCELED" || canceled.ID != created.ID {
		t.Fatalf("unexpected response: %+v", canceled)
	}

	// Cancel PENDING payment.
	pending := decode[paymentResponse](t, a.do("POST", "/payments", `{"merchant_id":"m_1","amount":"30.00","currency":"USD"}`))
	if r := a.do("POST", "/payments/"+pending.ID+"/authorize", ""); r.Code != http.StatusOK {
		t.Fatalf("authorize: %d %s", r.Code, r.Body)
	}
	rec = a.do("POST", "/payments/"+pending.ID+"/cancel", "")
	if rec.Code != http.StatusOK {
		t.Fatalf("cancel pending: %d %s", rec.Code, rec.Body)
	}
	if got := decode[paymentResponse](t, rec); got.Status != "CANCELED" {
		t.Fatalf("status = %s, want CANCELED", got.Status)
	}

	// Verify webhook event payment.canceled is delivered.
	if err := hooks.Flush(context.Background()); err != nil {
		t.Fatal(err)
	}
	if len(sender.deliveries) != 5 {
		t.Fatalf("deliveries = %d, want 5", len(sender.deliveries))
	}
	var last webhook.Event
	if err := json.Unmarshal(sender.deliveries[len(sender.deliveries)-1].Body, &last); err != nil {
		t.Fatal(err)
	}
	if last.Type != "payment.canceled" {
		t.Fatalf("last event type = %q, want payment.canceled", last.Type)
	}

	// Unknown ID returns 404 not_found.
	rec = a.do("POST", "/payments/pay_unknown/cancel", "")
	if rec.Code != http.StatusNotFound {
		t.Fatalf("unknown cancel status %d: %s", rec.Code, rec.Body)
	}
	if e := decode[errorBody](t, rec); e.Error.Code != "not_found" {
		t.Fatalf("code %q, want not_found", e.Error.Code)
	}

	// Canceling SUCCEEDED returns 409 invalid_transition.
	succ := a.createSucceeded("10.00", "USD")
	rec = a.do("POST", "/payments/"+succ.ID+"/cancel", "")
	if rec.Code != http.StatusConflict {
		t.Fatalf("cancel succeeded status %d: %s", rec.Code, rec.Body)
	}
	if e := decode[errorBody](t, rec); e.Error.Code != "invalid_transition" {
		t.Fatalf("code %q, want invalid_transition", e.Error.Code)
	}

	// Canceled payment cannot be canceled again, authorized, captured, declined or refunded.
	blocked := []struct {
		name, path, body string
	}{
		{"cancel again", "/payments/" + created.ID + "/cancel", ""},
		{"authorize", "/payments/" + created.ID + "/authorize", ""},
		{"capture", "/payments/" + created.ID + "/capture", ""},
		{"decline", "/payments/" + created.ID + "/decline", `{"reason":"late"}`},
		{"refund", "/payments/" + created.ID + "/refunds", `{"amount":"5.00"}`},
	}
	for _, tt := range blocked {
		t.Run(tt.name, func(t *testing.T) {
			r := a.do("POST", tt.path, tt.body)
			if r.Code != http.StatusConflict {
				t.Fatalf("status %d, want 409: %s", r.Code, r.Body)
			}
			if e := decode[errorBody](t, r); e.Error.Code != "invalid_transition" {
				t.Fatalf("code %q, want invalid_transition", e.Error.Code)
			}
		})
	}
}

